-- Expand child-friendly representative example words for DAEHAN grade 4.
with words(word,reading,meaning,child_explanation,chars) as (
 values
 ('가격','가격','물건이나 서비스의 값','물건을 사거나 팔 때 정한 값',array['價','格']),('감소','감소','수나 양이 줄어듦','수나 양이 전보다 줄어드는 것',array['減','少']),('개선','개선','더 좋게 고침','잘못되거나 불편한 것을 더 좋게 고치는 것',array['改','善']),('개인','개인','한 사람','여럿이 아닌 한 사람',array['個','人']),('건강','건강','몸과 마음이 튼튼한 상태','몸과 마음이 아프지 않고 튼튼한 상태',array['健','康']),('건설','건설','건물이나 시설을 세움','건물이나 길 같은 것을 새로 만드는 일',array['建','設']),('경쟁','경쟁','서로 앞서려고 겨룸','서로 더 잘하려고 겨루는 일',array['競','爭']),('고정','고정','움직이지 않게 정함','움직이거나 바뀌지 않도록 정해 두는 것',array['固','定']),('고향','고향','태어나거나 자란 곳','태어나거나 오래 자라 정든 곳',array['故','鄕']),('과제','과제','해야 할 일이나 공부','정해진 때까지 해야 하는 공부나 일',array['課','題']),('관광','관광','다른 곳의 경치나 문화를 구경함','다른 지역에 가서 경치나 문화를 둘러보는 일',array['觀','光']),('광고','광고','널리 알리는 일','상품이나 소식을 여러 사람에게 알리는 것',array['廣','告']),('구조','구조','여러 부분이 짜인 모양','여러 부분이 서로 연결되어 이루어진 모양',array['構','造']),('구급','구급','급한 환자를 도움','다치거나 아픈 사람을 급히 돕는 일',array['救','急']),('요구','요구','필요한 것을 바라거나 청함','필요한 것을 해 달라고 바라거나 말하는 것',array['要','求']),('장기','장기','긴 기간','오랫동안 이어지는 기간',array['長','期']),('규칙','규칙','함께 지키기로 정한 약속','여럿이 함께 지켜야 하는 정해진 약속',array['規','則']),('극장','극장','영화나 공연을 보는 곳','영화나 공연을 관람하는 장소',array['劇','場']),('공급','공급','필요한 것을 제공함','필요한 물건이나 서비스를 내어 주는 것',array['供','給']),('기간','기간','어느 때부터 어느 때까지의 시간','시작한 때부터 끝나는 때까지의 시간',array['期','間']),('기술','기술','일을 잘 해내는 방법이나 능력','어떤 일을 잘 해내기 위한 방법이나 솜씨',array['技','術']),('단체','단체','같은 목적을 가진 사람들의 모임','같은 목적을 위해 여러 사람이 만든 모임',array['團','體']),('상담','상담','서로 이야기하며 해결 방법을 찾음','걱정이나 문제를 이야기하며 도움을 구하는 것',array['相','談']),('도착','도착','목적한 곳에 이름','가려고 한 곳에 다다르는 것',array['到','着']),('냉수','냉수','찬물','차가운 물',array['冷','水']),('여행','여행','다른 곳으로 가서 보고 경험함','다른 지역에 가서 구경하고 경험하는 일',array['旅','行']),('연습','연습','익숙해지도록 되풀이함','잘할 수 있도록 여러 번 되풀이해 해 보는 것',array['練','習']),('명령','명령','무엇을 하라고 시킴','어떤 일을 하도록 지시하는 것',array['命','令']),('재료','재료','무엇을 만드는 데 쓰는 것','물건이나 음식을 만들 때 사용하는 것',array['材','料']),('육지','육지','물이 아닌 땅','바다나 강이 아닌 땅',array['陸','地']),('법률','법률','나라에서 정한 법','나라와 사회에서 지키도록 정한 법',array['法','律']),('희망','희망','앞으로 이루어지기를 바라는 마음','좋은 일이 이루어지기를 바라는 마음',array['希','望']),('무기','무기','싸움에 쓰는 도구','싸움이나 전투에 사용하는 도구',array['武','器']),('미래','미래','앞으로 올 때','지금보다 뒤에 다가올 시간',array['未','來']),('배수','배수','어떤 수를 몇 배 한 수','어떤 수를 한 번 이상 곱해 얻는 수',array['倍','數']),('변화','변화','모양이나 상태가 달라짐','전과 비교해 모습이나 상태가 달라지는 것',array['變','化']),('보고','보고','알아본 내용을 알려 줌','알아보거나 한 일을 다른 사람에게 알리는 것',array['報','告'])
), upserted as (
 insert into public.hanja_words(word,reading,meaning,child_explanation,content_status,source_note)
 select word,reading,meaning,child_explanation,'PUBLISHED','4급 예시어 1차 · 앱 자체 쉬운 뜻풀이 · 2026-10-05' from words
 on conflict(word,reading,meaning) do update set child_explanation=excluded.child_explanation,content_status='PUBLISHED',source_note=excluded.source_note returning id,word,reading,meaning
)
insert into public.hanja_word_map(word_id,hanja_id,position)
select hw.id,h.id,u.ord::integer from words w join upserted hw on hw.word=w.word and hw.reading=w.reading and hw.meaning=w.meaning
cross join lateral unnest(w.chars) with ordinality as u(ch,ord) join public.hanja h on h.character=u.ch on conflict do nothing;
do $body$ declare v_words integer; v_bad integer; begin
 select count(*) into v_words from public.hanja_words where source_note='4급 예시어 1차 · 앱 자체 쉬운 뜻풀이 · 2026-10-05';
 if v_words<>37 then raise exception 'Expected 37 grade-4 batch-1 words, got %',v_words; end if;
 select count(*) into v_bad from public.hanja_words w where w.source_note='4급 예시어 1차 · 앱 자체 쉬운 뜻풀이 · 2026-10-05' and (select count(*) from public.hanja_word_map m where m.word_id=w.id)<>char_length(w.word);
 if v_bad<>0 then raise exception 'Grade-4 batch-1 mapping integrity failure: %',v_bad; end if;
end $body$;